import { test, expect } from '@playwright/test';

test.describe('Error clearing on input correction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display an error message for invalid input', async ({ page }) => {
    await page.getByLabel('Input Field').fill('invalid input');
    await page.getByRole('button', { name: 'Submit' }).click();
    const errorMessage = await page.getByText('Invalid input, please correct it.');
    await expect(errorMessage).toBeVisible();
  });

  test('should clear the error message when input is corrected', async ({ page }) => {
    await page.getByLabel('Input Field').fill('invalid input');
    await page.getByRole('button', { name: 'Submit' }).click();
    await expect(page.getByText('Invalid input, please correct it.')).toBeVisible();

    await page.getByLabel('Input Field').fill('valid input');
    await page.getByRole('button', { name: 'Submit' }).click();
    await expect(page.getByText('Invalid input, please correct it.')).toBeHidden();
  });
});
